from __future__ import absolute_import
import logging
from taf.internal.aliasing import aliasing_scope
from selenium.webdriver.remote.webdriver import WebDriver
from taf.selenium.mobile.sbts.facade import Sbts
from taf.selenium.mobile.sbts.factory import SbtsFactory
from taf.selenium.mobile.sbts.utils import catch_intercepted_click_exception
from taf.selenium.mobile.core import core
from taf.selenium.mobile.core.common.utils import catch_interface_exception


class sbts(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(name=__name__, lookup_arg='sbts', lookup_type=Sbts)

    def __init__(self):
        super(sbts, self).__init__()
        self._driver = None
        self._debug_dir = None
        self._sbts_factory = SbtsFactory()

    def setup_sbts(self, browser, version=None, alias=None):
        """
        Create sbts web instance.

        :param browser: browser alias, should be created by "create_firefox_browser" or "create_chrome_browser"
        before use "setup_sbts" keyword and set the scope of browser
        :type browser: str
        :param version: sbts version, e.g. "SBTS", default is None
        :type version: str
        :param alias:  (optional) alias that the new sbts object will be identified by
        If not specified, default alias is used: "None"
        :type alias: str

        Usage example:
        1) use firefox browser to test sbts.
        *** Settings ***
        Library    taf.selenium.mobile.sbts    WITH NAME      sbts
        *** Variables ***
        ${device_name}    One Plus 8
        ${download_dir}   xxx
        ${browser_alias}    myDriver
        ${virtual_display}    ${True}
        ${sbts_alias}    sbts
        ${WEBUI_URL}    xxx.xxx.xxx.xxx
        ${WEBUI_NAME}    Nemuadmin
        ${WEBUI_PWD}     nemuuser
        ${browser_scope}    suite

        *** Test Cases ***
        Selenium Sbts Mobile TC
            Create Firefox Browser
            sbts.setup_sbts
            ...    browser=${browser_alias}
            ...    alias=${sbts_alias}
            sbts.teardown_sbts
            ...    sbts=${sbts_alias}
        *** Keywords ***
        Create Firefox Browser
            sbts.create_firefox_browser
            ...    name=${browser_alias}
            ...    download_dir=${download_dir}
            ...    screenshot_dir=${download_dir}
            ...    virtual_display=${virtual_display}
            ...    device_name=${device_name}
            sbts.set_scope    alias=${browser_alias}    scope=${browser_scope}
        2) use chrome browser to test sbts.
        *** Settings ***
        Library    taf.selenium.mobile.sbts    WITH NAME      sbts
        *** Variables ***
        ${device_name}    One Plus 8
        ${download_dir}   xxx
        ${browser_alias}    myDriver
        ${virtual_display}    ${True}
        ${preferences_file}    xxx
        ${sbts_alias}    sbts
        ${sbts_version}    SBTS22R1
        ${WEBUI_URL}    xxx.xxx.xxx.xxx
        ${WEBUI_NAME}    Nemuadmin
        ${WEBUI_PWD}     nemuuser
        ${browser_scope}    suite

        *** Test Cases ***
        Selenium Sbts Mobile TC
            Create Chrome Browser
            sbts.setup_sbts
            ...    browser=${browser_alias}
            ...    version=${sbts_version}
            ...    alias=${sbts_alias}
            sbts.teardown_sbts
            ...    sbts=${sbts_alias}
        *** Keywords ***
        Create Chrome Browser
            sbts.create_chrome_browser
            ...    name=${browser_alias}
            ...    download_dir=${download_dir}
            ...    screenshot_dir=${download_dir}
            ...    virtual_display=${virtual_display}
            ...    device_name=${device_name}
            ...    preferences_file=${preferences_file}
            sbts.set_scope    alias=${browser_alias}    scope=${browser_scope}
        """
        driver_obj = self.get_alias_value(browser)
        if driver_obj and isinstance(driver_obj, WebDriver):
            self._driver = driver_obj
            logging.info('WebDriver named "{}" with ID {} is created successfully'.format(browser, self._driver))
        else:
            raise AttributeError('Can not find the WebDriver named "{}", '
                  'please use create_firefox_browser or create_chrome_browser to create one'.format(browser))
        sbts = self._sbts_factory.create(self._driver, self._download_checker, self._screenshot_dir, version)
        self.store.add(sbts, alias)

    @lookup_handler.implicit_lookup
    def login(self, url, username, password, timeout=60, sbts=None):
        """
        Keyword for login into sbts web.

        :param url: url to sbts web
        :type url: str
        :param username: username, e.g. 'Nemuadmin'
        :type username: str
        :param password: password, e.g. 'nemuuser'
        :type password: str
        :param timeout: timeout, default value is 60 seconds.
        :type timeout: int
        :param sbts:  (optional) alias that the new sbts object will be identified by
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.login_management.sbts_login_management.login(url, username, password, int(timeout))

    @catch_intercepted_click_exception
    @lookup_handler.implicit_lookup
    def logout(self, timeout=60, retry=None, sbts=None):
        """
        Keyword for logout from sbts web.

        :param timeout: timeout, default value is 60 seconds.
        :type timeout: int
        :param retry: retry time for logout
        :type retry: int
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.login_management.sbts_login_management.logout(int(timeout))

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def login_for_lab_access(self, url, username, password, timeout=60, sbts=None):
        """
        Keyword for login into lab web.

        :param url: url to lab web
        :type url: str
        :param username: username
        :type username: str
        :param password: password
        :type password: str
        :param timeout: timeout, default value is 60 seconds.
        :type timeout: int
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by
        If not specified, default alias is used: "None"
        """
        sbts.login_management.lab_access_login_management.login(url, username, password, int(timeout))

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def save_screenshot(self, filename, screenshot_dir=None, sbts=None):
        """
        Keyword for save screen shot, tester can add this keyword after failed test case to provide clues for developer

        :param filename: png file name, please keep it unique
        :type filename: str
        :param screenshot_dir: screen shot path, user should have permission to read and write this dir
        :type screenshot_dir: str or None
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.debug.save_screenshot(filename, screenshot_dir)

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def disable_message_box(self, sbts=None):
        """
        Keyword for stop message box shown to avoid menu being covered by message box, when first log in or page
        reloaded, please call this method once.

        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.debug.disable_message_box()

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def get_bts_basic_info(self, sbts=None):
        """
        Keyword for getting bts basic info

        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        :return: bts basic info
        :rtype: dict
        """
        sbts.bts_status.site_view.navigate_to(sbts.menu_list.site_view_page)
        return sbts.bts_status.site_view.get_bts_basic_info()

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def close_bts_basic_info(self, sbts=None):
        """
        Keyword for closing bts basic info window

        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        :return: None
        """
        sbts.bts_status.site_view.navigate_to(sbts.menu_list.site_view_page)
        return sbts.bts_status.site_view.close_bts_basic_info()

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def reset_site(self, sbts=None):
        """
        keyword for click 'reset' button to Reset Site
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.bts_status.site_view.navigate_to(sbts.menu_list.site_view_page)
        sbts.bts_status.site_view.reset_site()

    @catch_interface_exception
    @catch_intercepted_click_exception
    @lookup_handler.implicit_lookup
    def reset_capacity_unit(self, capacity_unit, timeout=10, sbts=None):
        """
        keyword for click 'reset' button to reset hardware unit

        :param capacity_unit: hardware unit, e.g. 'RMOD-1', 'BBMOD-1'
        :type capacity_unit: str
        :param timeout: timeout, default value is 10 seconds.
        :type timeout: str or int
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.bts_status.site_view.navigate_to(sbts.menu_list.site_view_page)
        sbts.bts_status.site_view.reset_hardware(capacity_unit, int(timeout))

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def software_rollback(self, sbts=None):
        """
        Keyword for rollback software in 'Software Update' page
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.software.software_management.navigate_to(sbts.menu_list.software_management_page)
        sbts.software.software_management.software_rollback()

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def check_current_software_version(self, key=None, sbts=None):
        """
        Keyword for checking software version in 'Software Update' page

        :param key: str, only support 'Active', 'Passive', 'Planned' and None
        :type key: str
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        :return: if key is none, return dict contain all software version, if key is specific, return
                              corresponding value
        :rtype: dict or str
        """
        sbts.software.software_management.navigate_to(sbts.menu_list.software_management_page)
        return sbts.software.software_management.check_current_software_version(key)

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def start_up_view_window_exists(self, timeout=5, sbts=None):
        """
        Keyword for waiting for start up view window appears. If appears, return True, otherwise, return False

        :param timeout: timeout, default 5
        :type timeout: int
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        :return: True or False
        :rtype: bool
        """
        return sbts.bts_start_up_view_modal.wait_for_start_up_view_modal_appear(int(timeout))

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def close_start_up_view_window(self, timeout=60, sbts=None):
        """
        Keyword for closing start up view window

        :param timeout: timeout, default 60
        :type timeout: int
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.bts_start_up_view_modal.close(int(timeout))

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def close_browser(self, sbts=None):
        """
        Keyword for close browser
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.browser.close_browser()

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def teardown_sbts(self, sbts=None):
        """
        Keyword for close browser
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
        If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.browser.close_browser()
        self.disable_virtual_display()
